insert into public.recipes (title_en, title_km, description_en, description_km, calories, cuisine, category, prep_minutes, servings, difficulty, is_trending, popularity, image_url, image_credit, image_page, ingredients_en, ingredients_km, steps_en, steps_km) values
('Pho Bo', 'ផើសាច់គោ', 'Vietnamese beef noodle soup with a star anise and ginger broth.', 'គុយទាវសាច់គោវៀតណាម ជាមួយទឹកស៊ុបផ្កាចន្ទ និងខ្ញី។', 420, 'VN', 'noodles', 90, 4, 'hard', false, 70, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Beef_noodle_soup_%28Ph%E1%BB%9F_b%C3%B2%29_-_Pho_Hanoi_Authentic_2024-12-01.jpg/500px-Beef_noodle_soup_%28Ph%E1%BB%9F_b%C3%B2%29_-_Pho_Hanoi_Authentic_2024-12-01.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Beef_noodle_soup_(Ph%E1%BB%9F_b%C3%B2)_-_Pho_Hanoi_Authentic_2024-12-01.jpg', '["1 kg beef bones", "400 g rice noodles", "2 star anise and 1 cinnamon stick", "1 piece ginger", "200 g thin beef slices", "Herbs, bean sprouts and lime"]'::jsonb, '["ឆ្អឹងគោ ១ គីឡូក្រាម", "គុយទាវ ៤០០ ក្រាម", "ផ្កាចន្ទ ២ និងសំបកឈើក្រអូប ១", "ខ្ញី ១ ដុំ", "សាច់គោហាន់ស្តើង ២០០ ក្រាម", "ជីរ សណ្តែកបណ្តុះ និងក្រូចឆ្មា"]'::jsonb, '["Simmer the bones with toasted spices and ginger for 2 hours.", "Cook the noodles and put them in bowls with raw beef.", "Pour the boiling broth over and add herbs and lime."]'::jsonb, '["រំងាស់ឆ្អឹងជាមួយគ្រឿងទេសលីង និងខ្ញី ២ ម៉ោង។", "ស្ងោរគុយទាវ ដាក់ក្នុងចានជាមួយសាច់គោឆៅ។", "ចាក់ទឹកស៊ុបពុះពីលើ ហើយដាក់ជីរ និងក្រូចឆ្មា។"]'::jsonb),
('Banh Xeo', 'នំបាញ់ឆែវ', 'Crispy turmeric rice pancake filled with shrimp, pork and bean sprouts.', 'នំបាញ់ឆែវម្សៅអង្ករលាយរមៀតស្រួយ ញាត់បង្គា សាច់ជ្រូក និងសណ្តែកបណ្តុះ។', 410, 'VN', 'snack', 40, 4, 'medium', true, 69, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Crispy_Vietnamese_Pancake_%28Banh_Xeo%29_-_Xin_Chao%2C_Eastbourne_2026-08-14_%281%29.jpg/500px-Crispy_Vietnamese_Pancake_%28Banh_Xeo%29_-_Xin_Chao%2C_Eastbourne_2026-08-14_%281%29.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Crispy_Vietnamese_Pancake_(Banh_Xeo)_-_Xin_Chao,_Eastbourne_2026-08-14_(1).jpg', '["200 g rice flour", "200 ml coconut milk", "1 tsp turmeric", "150 g shrimp", "100 g pork belly", "Bean sprouts and lettuce"]'::jsonb, '["ម្សៅអង្ករ ២០០ ក្រាម", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ម្សៅរមៀត ១ ស្លាបព្រាកាហ្វេ", "បង្គា ១៥០ ក្រាម", "សាច់ជ្រូកបីជាន់ ១០០ ក្រាម", "សណ្តែកបណ្តុះ និងសាឡាត់"]'::jsonb, '["Whisk the flour, coconut milk, turmeric and water into a thin batter.", "Fry the pork and shrimp, pour in batter and swirl.", "Add bean sprouts, cover, then fold when crisp. Wrap in lettuce to eat."]'::jsonb, '["លាយម្សៅ ខ្ទិះដូង រមៀត និងទឹកឱ្យរាវ។", "ឆាសាច់ជ្រូក និងបង្គា រួចចាក់ម្សៅ ហើយគ្រវីឱ្យរាល។", "ដាក់សណ្តែកបណ្តុះ គ្រប ហើយបត់ពេលស្រួយ។ ខ្ចប់សាឡាត់ញ៉ាំ។"]'::jsonb),
('Ca Phe Sua Da', 'កាហ្វេទឹកដោះគោទឹកកក', 'Strong drip coffee with sweet condensed milk over ice.', 'កាហ្វេដាំខ្លាំង ជាមួយទឹកដោះគោខាប់ និងទឹកកក។', 190, 'VN', 'drinks', 10, 1, 'easy', false, 68, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Ca_Phe_Sua_Da.jpg/500px-Ca_Phe_Sua_Da.jpg', 'Photo: Clarin, CC BY 2.5, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ca_Phe_Sua_Da.jpg', '["2 tbsp dark ground coffee", "2 tbsp condensed milk", "100 ml hot water", "Ice"]'::jsonb, '["ម្សៅកាហ្វេខ្មៅ ២ ស្លាបព្រាបាយ", "ទឹកដោះគោខាប់ ២ ស្លាបព្រាបាយ", "ទឹកក្តៅ ១០០ មីលីលីត្រ", "ទឹកកក"]'::jsonb, '["Put condensed milk in a glass.", "Drip the coffee through a phin filter over it.", "Stir and pour over ice."]'::jsonb, '["ដាក់ទឹកដោះគោខាប់ក្នុងកែវ។", "ចម្រោះកាហ្វេតាមតម្រងភីនពីលើ។", "កូរ ហើយចាក់លើទឹកកក។"]'::jsonb),
('Larb', 'ឡាប', 'Lao minced chicken salad with lime, toasted rice and mint.', 'ញាំសាច់មាន់ចិញ្ច្រាំឡាវ ជាមួយក្រូចឆ្មា អង្ករលីង និងជីរអង្កាម។', 310, 'LA', 'salad', 25, 2, 'easy', false, 66, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Day_224-_Chicken_Larb_%287947748382%29.jpg/500px-Day_224-_Chicken_Larb_%287947748382%29.jpg', 'Photo: Sodanie Chea from Norwalk, Ca, United States, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Day_224-_Chicken_Larb_(7947748382).jpg', '["300 g minced chicken", "2 tbsp lime juice", "1 tbsp fish sauce", "1 tbsp toasted rice powder", "2 shallots", "Mint and cilantro"]'::jsonb, '["សាច់មាន់ចិញ្ច្រាំ ៣០០ ក្រាម", "ទឹកក្រូចឆ្មា ២ ស្លាបព្រាបាយ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "អង្ករលីងបុក ១ ស្លាបព្រាបាយ", "ខ្ទឹមក្រហម ២ មើម", "ជីរអង្កាម និងជីវ៉ាន់ស៊ុយ"]'::jsonb, '["Cook the chicken in a dry pan with a splash of water.", "Mix with lime, fish sauce, shallots and rice powder.", "Toss with fresh herbs and serve with sticky rice."]'::jsonb, '["ឆាសាច់មាន់ក្នុងខ្ទះ ជាមួយទឹកបន្តិច។", "លាយទឹកក្រូចឆ្មា ទឹកត្រី ខ្ទឹមក្រហម និងអង្ករលីង។", "ច្របល់ជីរស្រស់ ហើយញ៉ាំជាមួយបាយដំណើប។"]'::jsonb),
('Tam Mak Hoong', 'បុកល្ហុងឡាវ', 'Spicy pounded green papaya salad, Lao style.', 'បុកល្ហុងហឹរ តាមរបៀបឡាវ។', 150, 'LA', 'salad', 15, 2, 'easy', false, 65, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Lao_green_papaya_salad.jpg/500px-Lao_green_papaya_salad.jpg', 'Photo: Jpatokal, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lao_green_papaya_salad.jpg', '["2 cups shredded green papaya", "2 chilies", "2 cloves garlic", "1 tomato", "1 tbsp fish sauce", "1 lime"]'::jsonb, '["ល្ហុងខ្ចីចិត ២ កែវ", "ម្ទេស ២ គ្រាប់", "ខ្ទឹមស ២ កំពឹស", "ប៉េងប៉ោះ ១ ផ្លែ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ក្រូចឆ្មា ១ ផ្លែ"]'::jsonb, '["Pound the chilies and garlic in a mortar.", "Add tomato, fish sauce and lime and bruise lightly.", "Add the papaya and pound gently until mixed."]'::jsonb, '["បុកម្ទេស និងខ្ទឹមសក្នុងត្បាល់។", "ដាក់ប៉េងប៉ោះ ទឹកត្រី និងក្រូចឆ្មា បុកស្រាលៗ។", "ដាក់ល្ហុង ហើយបុកថ្នមៗឱ្យសព្វ។"]'::jsonb),
('Mohinga', 'មហ៊ីងហ្គា', 'Burmese fish and lemongrass noodle soup, eaten for breakfast.', 'គុយទាវទឹកត្រីស្លឹកគ្រៃភូមា សម្រាប់អាហារពេលព្រឹក។', 400, 'MM', 'noodles', 60, 4, 'medium', false, 64, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Mohinga_bowl.jpg/500px-Mohinga_bowl.jpg', 'Photo: Junosang, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mohinga_bowl.jpg', '["300 g catfish", "300 g thin rice noodles", "2 stalks lemongrass", "2 tbsp chickpea flour", "1 onion", "Boiled eggs and lime"]'::jsonb, '["ត្រីអណ្តែង ៣០០ ក្រាម", "មីអង្ករស្តើង ៣០០ ក្រាម", "ស្លឹកគ្រៃ ២ ដើម", "ម្សៅសណ្តែកងួរ ២ ស្លាបព្រាបាយ", "ខ្ទឹមបារាំង ១ មើម", "ស៊ុតស្ងោរ និងក្រូចឆ្មា"]'::jsonb, '["Poach the fish with lemongrass and flake it.", "Fry onion, add the fish and broth, and thicken with chickpea flour.", "Serve over noodles with egg and lime."]'::jsonb, '["ស្ងោរត្រីជាមួយស្លឹកគ្រៃ ហើយបកយកសាច់។", "លីងខ្ទឹមបារាំង ដាក់ត្រី និងទឹកស៊ុប រួចធ្វើឱ្យខាប់ដោយម្សៅសណ្តែក។", "ចាក់លើមី ជាមួយស៊ុត និងក្រូចឆ្មា។"]'::jsonb),
('Lahpet Thoke', 'ញាំស្លឹកតែភូមា', 'Burmese fermented tea leaf salad with crunchy beans and nuts.', 'ញាំស្លឹកតែជ្រលក់ភូមា ជាមួយសណ្តែក និងគ្រាប់ស្រួយ។', 280, 'MM', 'salad', 15, 2, 'easy', false, 63, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/Fermented_Tea_Leaf_Salad.jpg/500px-Fermented_Tea_Leaf_Salad.jpg', 'Photo: Saosukham, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fermented_Tea_Leaf_Salad.jpg', '["3 tbsp fermented tea leaves", "2 cups shredded cabbage", "1 tomato", "3 tbsp fried beans and peanuts", "1 tbsp sesame seeds", "1 lime"]'::jsonb, '["ស្លឹកតែជ្រលក់ ៣ ស្លាបព្រាបាយ", "ស្ពៃក្តោបចិត ២ កែវ", "ប៉េងប៉ោះ ១ ផ្លែ", "សណ្តែកចៀន និងសណ្តែកដី ៣ ស្លាបព្រាបាយ", "ល្ង ១ ស្លាបព្រាបាយ", "ក្រូចឆ្មា ១ ផ្លែ"]'::jsonb, '["Put the cabbage and tomato in a bowl.", "Add the tea leaves, beans, peanuts and sesame.", "Squeeze over lime and toss just before eating."]'::jsonb, '["ដាក់ស្ពៃក្តោប និងប៉េងប៉ោះក្នុងចាន។", "ដាក់ស្លឹកតែ សណ្តែក សណ្តែកដី និងល្ង។", "ច្របាច់ក្រូចឆ្មា ហើយច្របល់មុនញ៉ាំ។"]'::jsonb),
('Mapo Tofu', 'តៅហ៊ូម៉ាប៉ូ', 'Sichuan tofu in a spicy, numbing chili and bean sauce with minced pork.', 'តៅហ៊ូស៊ីឈួន ក្នុងទឹកម្ទេសសណ្តែកហឹរ ជាមួយសាច់ជ្រូកចិញ្ច្រាំ។', 380, 'CN', 'main', 25, 3, 'medium', false, 62, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/Authentic_Mapo_Tofu.jpg/500px-Authentic_Mapo_Tofu.jpg', 'Photo: Sichuanfoodlover, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Authentic_Mapo_Tofu.jpg', '["400 g soft tofu", "100 g minced pork", "2 tbsp chili bean paste", "1 tsp Sichuan pepper", "2 cloves garlic", "1 tsp cornstarch"]'::jsonb, '["តៅហ៊ូទន់ ៤០០ ក្រាម", "សាច់ជ្រូកចិញ្ច្រាំ ១០០ ក្រាម", "ទឹកម្ទេសសណ្តែក ២ ស្លាបព្រាបាយ", "ម្រេចស៊ីឈួន ១ ស្លាបព្រាកាហ្វេ", "ខ្ទឹមស ២ កំពឹស", "ម្សៅពោត ១ ស្លាបព្រាកាហ្វេ"]'::jsonb, '["Fry the pork until crisp, then add the bean paste and garlic.", "Add water and the cubed tofu and simmer for 5 minutes.", "Thicken with cornstarch and sprinkle with Sichuan pepper."]'::jsonb, '["ឆាសាច់ជ្រូកឱ្យស្រួយ រួចដាក់ទឹកម្ទេសសណ្តែក និងខ្ទឹមស។", "ចាក់ទឹក ដាក់តៅហ៊ូកាត់ដុំ ហើយរំងាស់ ៥ នាទី។", "ធ្វើឱ្យខាប់ដោយម្សៅពោត ហើយរោយម្រេចស៊ីឈួន។"]'::jsonb),
('Kung Pao Chicken', 'សាច់មាន់គុងប៉ាវ', 'Stir-fried chicken with peanuts, dried chilies and a sweet-sour sauce.', 'សាច់មាន់ឆាជាមួយសណ្តែកដី ម្ទេសក្រៀម និងទឹកជូរផ្អែម។', 450, 'CN', 'main', 25, 2, 'easy', false, 61, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Kung_Pao_chicken_%28western_version%29_-1.jpg/500px-Kung_Pao_chicken_%28western_version%29_-1.jpg', 'Photo: Alexander Marks (aomarks), Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kung_Pao_chicken_(western_version)_-1.jpg', '["300 g chicken thigh", "50 g roasted peanuts", "6 dried chilies", "2 tbsp soy sauce", "1 tbsp black vinegar", "1 tbsp sugar"]'::jsonb, '["សាច់ភ្លៅមាន់ ៣០០ ក្រាម", "សណ្តែកដីលីង ៥០ ក្រាម", "ម្ទេសក្រៀម ៦ គ្រាប់", "ទឹកស៊ីអ៊ីវ ២ ស្លាបព្រាបាយ", "ទឹកខ្មេះខ្មៅ ១ ស្លាបព្រាបាយ", "ស្ករ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Cube the chicken and coat with a little soy sauce.", "Fry the chilies briefly, then stir-fry the chicken until cooked.", "Add the sauce and peanuts and toss for 1 minute."]'::jsonb, '["កាត់សាច់មាន់ជាដុំ ហើយប្រឡាក់ទឹកស៊ីអ៊ីវបន្តិច។", "លីងម្ទេសក្រៀមបន្តិច រួចឆាសាច់មាន់ឱ្យឆ្អិន។", "ដាក់ទឹកជ្រលក់ និងសណ្តែកដី ឆា ១ នាទី។"]'::jsonb),
('Oyakodon', 'បាយមាន់ស៊ុតជប៉ុន', 'Japanese rice bowl topped with chicken and soft egg simmered in sweet soy broth.', 'បាយជប៉ុន ដាក់សាច់មាន់ និងស៊ុតទន់ រំងាស់ក្នុងទឹកស៊ីអ៊ីវផ្អែម។', 620, 'JP', 'rice', 20, 2, 'easy', false, 60, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Oyakodon_003.jpg/500px-Oyakodon_003.jpg', 'Photo: Ocdp, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Oyakodon_003.jpg', '["2 bowls cooked rice", "200 g chicken thigh", "3 eggs", "1 onion", "3 tbsp soy sauce", "1 tbsp sugar"]'::jsonb, '["បាយ ២ ចាន", "សាច់ភ្លៅមាន់ ២០០ ក្រាម", "ស៊ុត ៣ គ្រាប់", "ខ្ទឹមបារាំង ១ មើម", "ទឹកស៊ីអ៊ីវ ៣ ស្លាបព្រាបាយ", "ស្ករ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Simmer the onion in soy sauce, sugar and water.", "Add the chicken and cook for 5 minutes.", "Pour in beaten eggs, cover for 1 minute and slide onto rice."]'::jsonb, '["រំងាស់ខ្ទឹមបារាំងក្នុងទឹកស៊ីអ៊ីវ ស្ករ និងទឹក។", "ដាក់សាច់មាន់ ស្ងោរ ៥ នាទី។", "ចាក់ស៊ុតវាយ គរ ១ នាទី ហើយដាក់លើបាយ។"]'::jsonb),
('Miso Soup', 'ស៊ុបមីសូ', 'Light Japanese soup of miso, tofu and seaweed.', 'ស៊ុបជប៉ុនស្រាល ជាមួយមីសូ តៅហ៊ូ និងសារាយសមុទ្រ។', 90, 'JP', 'soup', 10, 2, 'easy', false, 59, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Miso_Soup_001.jpg/500px-Miso_Soup_001.jpg', 'Photo: Ocdp, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Miso_Soup_001.jpg', '["500 ml dashi stock", "2 tbsp miso paste", "100 g soft tofu", "1 tbsp dried wakame", "1 spring onion"]'::jsonb, '["ទឹកស៊ុបដាស៊ី ៥០០ មីលីលីត្រ", "មីសូ ២ ស្លាបព្រាបាយ", "តៅហ៊ូទន់ ១០០ ក្រាម", "សារាយវ៉ាកាមេ ១ ស្លាបព្រាបាយ", "ស្លឹកខ្ទឹម ១ ដើម"]'::jsonb, '["Heat the dashi without boiling.", "Add the tofu cubes and wakame for 2 minutes.", "Turn off the heat, stir in the miso and top with spring onion."]'::jsonb, '["កម្តៅទឹកដាស៊ី កុំឱ្យពុះ។", "ដាក់តៅហ៊ូ និងវ៉ាកាមេ ២ នាទី។", "បិទភ្លើង កូរមីសូ ហើយរោយស្លឹកខ្ទឹម។"]'::jsonb),
('Bibimbap', 'ប៊ីប៊ីមបាប', 'Korean rice bowl with seasoned vegetables, beef, egg and chili paste.', 'បាយកូរ៉េ ជាមួយបន្លែប្រឡាក់ សាច់គោ ស៊ុត និងទឹកម្ទេសកូរ៉េ។', 590, 'KR', 'rice', 40, 2, 'medium', true, 58, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Seoul_Bibimbap_%28beef%29_-_Time_For_Kimchi.jpg/500px-Seoul_Bibimbap_%28beef%29_-_Time_For_Kimchi.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Seoul_Bibimbap_(beef)_-_Time_For_Kimchi.jpg', '["2 bowls cooked rice", "150 g beef", "1 carrot and 1 zucchini", "100 g spinach", "2 eggs", "2 tbsp gochujang"]'::jsonb, '["បាយ ២ ចាន", "សាច់គោ ១៥០ ក្រាម", "ការ៉ុត ១ និងត្រសក់បារាំង ១", "ស្ពៃខៀវ ១០០ ក្រាម", "ស៊ុត ២ គ្រាប់", "ទឹកម្ទេសកូរ៉េ ២ ស្លាបព្រាបាយ"]'::jsonb, '["Stir-fry the beef and each vegetable separately with a little sesame oil.", "Fry the eggs sunny side up.", "Arrange everything on the rice and mix in gochujang to eat."]'::jsonb, '["ឆាសាច់គោ និងបន្លែម្តងមួយមុខ ជាមួយប្រេងល្ងបន្តិច។", "ចៀនស៊ុតពងទា។", "រៀបទាំងអស់លើបាយ ហើយច្របល់ទឹកម្ទេសកូរ៉េពេលញ៉ាំ។"]'::jsonb),
('Kimchi Jjigae', 'ស៊ុបគីមឈី', 'Spicy Korean kimchi stew with pork and tofu.', 'ស៊ុបគីមឈីកូរ៉េហឹរ ជាមួយសាច់ជ្រូក និងតៅហ៊ូ។', 330, 'KR', 'soup', 30, 2, 'easy', false, 57, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Kimchi_jjigae_-_Kogi%2C_Brighton_2023-11-15.jpg/500px-Kimchi_jjigae_-_Kogi%2C_Brighton_2023-11-15.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kimchi_jjigae_-_Kogi,_Brighton_2023-11-15.jpg', '["200 g aged kimchi", "150 g pork belly", "150 g tofu", "1 tbsp gochugaru", "1 spring onion", "500 ml water"]'::jsonb, '["គីមឈីចាស់ ២០០ ក្រាម", "សាច់ជ្រូកបីជាន់ ១៥០ ក្រាម", "តៅហ៊ូ ១៥០ ក្រាម", "ម្សៅម្ទេសកូរ៉េ ១ ស្លាបព្រាបាយ", "ស្លឹកខ្ទឹម ១ ដើម", "ទឹក ៥០០ មីលីលីត្រ"]'::jsonb, '["Fry the pork, then add the kimchi and chili flakes.", "Add water and simmer for 15 minutes.", "Add the tofu and spring onion and cook for 5 more minutes."]'::jsonb, '["ឆាសាច់ជ្រូក រួចដាក់គីមឈី និងម្សៅម្ទេស។", "ចាក់ទឹក ហើយរំងាស់ ១៥ នាទី។", "ដាក់តៅហ៊ូ និងស្លឹកខ្ទឹម ស្ងោរ ៥ នាទីទៀត។"]'::jsonb),
('Chana Masala', 'ការីសណ្តែកងួរ', 'North Indian chickpea curry with tomato, onion and warm spices.', 'ការីសណ្តែកងួរឥណ្ឌាខាងជើង ជាមួយប៉េងប៉ោះ ខ្ទឹមបារាំង និងគ្រឿងទេស។', 360, 'IN', 'curry', 35, 4, 'easy', false, 56, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Chana_Masala_-_Mohammed_-_Spice_Of_Life_2024-05-27.jpg/500px-Chana_Masala_-_Mohammed_-_Spice_Of_Life_2024-05-27.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chana_Masala_-_Mohammed_-_Spice_Of_Life_2024-05-27.jpg', '["2 cans chickpeas", "2 onions", "3 tomatoes", "1 piece ginger and 3 cloves garlic", "2 tsp garam masala", "Cilantro"]'::jsonb, '["សណ្តែកងួរ ២ កំប៉ុង", "ខ្ទឹមបារាំង ២ មើម", "ប៉េងប៉ោះ ៣ ផ្លែ", "ខ្ញី ១ ដុំ និងខ្ទឹមស ៣ កំពឹស", "ម្សៅហ្គារ៉ាម ម៉ាសាឡា ២ ស្លាបព្រាកាហ្វេ", "ជីវ៉ាន់ស៊ុយ"]'::jsonb, '["Fry the onions until golden, then add ginger and garlic.", "Add tomatoes and spices and cook into a thick sauce.", "Add the chickpeas, simmer for 15 minutes and top with cilantro."]'::jsonb, '["លីងខ្ទឹមបារាំងឱ្យលឿង រួចដាក់ខ្ញី និងខ្ទឹមស។", "ដាក់ប៉េងប៉ោះ និងគ្រឿងទេស ឆាឱ្យខាប់។", "ដាក់សណ្តែកងួរ រំងាស់ ១៥ នាទី ហើយរោយជីវ៉ាន់ស៊ុយ។"]'::jsonb),
('Mango Lassi', 'ឡាស៊ីស្វាយ', 'Creamy Indian yogurt drink blended with ripe mango.', 'ភេសជ្ជៈយ៉ាអួឥណ្ឌា ក្រឡុកជាមួយស្វាយទុំ។', 220, 'IN', 'drinks', 5, 2, 'easy', false, 55, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Mango_Lassi_and_Butter_Milk_-_Vel_South_Indian_Kitchen_%2B_Bar.jpg/500px-Mango_Lassi_and_Butter_Milk_-_Vel_South_Indian_Kitchen_%2B_Bar.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mango_Lassi_and_Butter_Milk_-_Vel_South_Indian_Kitchen_%2B_Bar.jpg', '["1 ripe mango", "250 g plain yogurt", "100 ml milk", "1 tbsp sugar", "Ice"]'::jsonb, '["ស្វាយទុំ ១ ផ្លែ", "យ៉ាអួ ២៥០ ក្រាម", "ទឹកដោះគោ ១០០ មីលីលីត្រ", "ស្ករ ១ ស្លាបព្រាបាយ", "ទឹកកក"]'::jsonb, '["Peel and chop the mango.", "Blend with yogurt, milk and sugar until smooth.", "Serve cold over ice."]'::jsonb, '["ចិតស្វាយ ហើយកាត់ជាដុំ។", "ក្រឡុកជាមួយយ៉ាអួ ទឹកដោះគោ និងស្ករឱ្យម៉ត់។", "ចាក់លើទឹកកក ហើយផឹកត្រជាក់ៗ។"]'::jsonb),
('Chicken Adobo', 'សាច់មាន់អាដូបូ', 'Filipino chicken braised in vinegar, soy sauce, garlic and bay leaves.', 'សាច់មាន់ហ្វីលីពីន ខដោយទឹកខ្មេះ ទឹកស៊ីអ៊ីវ ខ្ទឹមស និងស្លឹកបេ។', 470, 'PH', 'main', 45, 4, 'easy', false, 54, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Chicken_adobo.jpg/500px-Chicken_adobo.jpg', 'Photo: dbgg1979 on flickr, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Chicken_adobo.jpg', '["800 g chicken pieces", "120 ml soy sauce", "80 ml vinegar", "1 head garlic", "3 bay leaves", "1 tsp black peppercorns"]'::jsonb, '["សាច់មាន់ ៨០០ ក្រាម", "ទឹកស៊ីអ៊ីវ ១២០ មីលីលីត្រ", "ទឹកខ្មេះ ៨០ មីលីលីត្រ", "ខ្ទឹមស ១ មើម", "ស្លឹកបេ ៣ សន្លឹក", "គ្រាប់ម្រេច ១ ស្លាបព្រាកាហ្វេ"]'::jsonb, '["Put everything in a pot and marinate for 30 minutes.", "Simmer covered for 30 minutes.", "Uncover and reduce the sauce until glossy. Serve with rice."]'::jsonb, '["ដាក់គ្រប់មុខក្នុងឆ្នាំង ហើយប្រឡាក់ ៣០ នាទី។", "គ្របហើយរំងាស់ ៣០ នាទី។", "បើកគម្រប ខឱ្យទឹករីងភ្លឺ។ ញ៉ាំជាមួយបាយ។"]'::jsonb),
('Halo-Halo', 'ហាឡូហាឡូ', 'Filipino shaved ice dessert with sweet beans, fruit, milk and ube ice cream.', 'បង្អែមទឹកកកឈូសហ្វីលីពីន ជាមួយសណ្តែកផ្អែម ផ្លែឈើ ទឹកដោះគោ និងការ៉េមដំឡូងស្វាយ។', 350, 'PH', 'sweet', 15, 2, 'easy', false, 53, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Halo_halo_%2828049395903%29.jpg/500px-Halo_halo_%2828049395903%29.jpg', 'Photo: T.Tseng, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Halo_halo_(28049395903).jpg', '["2 cups shaved ice", "4 tbsp sweet beans and jellies", "Ripe jackfruit or banana", "120 ml evaporated milk", "2 scoops ube ice cream"]'::jsonb, '["ទឹកកកឈូស ២ កែវ", "សណ្តែកផ្អែម និងចាហួយ ៤ ស្លាបព្រាបាយ", "ខ្នុរទុំ ឬចេក", "ទឹកដោះគោខាប់រាវ ១២០ មីលីលីត្រ", "ការ៉េមដំឡូងស្វាយ ២ ដុំ"]'::jsonb, '["Put the beans, jellies and fruit in tall glasses.", "Pack shaved ice on top and pour over the milk.", "Top with ube ice cream and mix before eating."]'::jsonb, '["ដាក់សណ្តែក ចាហួយ និងផ្លែឈើក្នុងកែវខ្ពស់។", "ដាក់ទឹកកកឈូសពីលើ ហើយចាក់ទឹកដោះគោ។", "ដាក់ការ៉េមពីលើ ហើយកូរមុនញ៉ាំ។"]'::jsonb),
('Nasi Goreng', 'បាយឆាឥណ្ឌូនេស៊ី', 'Indonesian sweet soy fried rice served with a fried egg.', 'បាយឆាឥណ្ឌូនេស៊ី ជាមួយទឹកស៊ីអ៊ីវផ្អែម និងស៊ុតចៀន។', 560, 'ID', 'rice', 20, 2, 'easy', false, 52, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Gili_Meno_Island%2C_Nasi_goreng%2C_Fried_rice_with_juice%2C_Indonesia.jpg/500px-Gili_Meno_Island%2C_Nasi_goreng%2C_Fried_rice_with_juice%2C_Indonesia.jpg', 'Photo: Vyacheslav Argenberg, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gili_Meno_Island,_Nasi_goreng,_Fried_rice_with_juice,_Indonesia.jpg', '["2 cups day-old rice", "2 shallots and 2 cloves garlic", "1 chili", "2 tbsp kecap manis (sweet soy)", "2 eggs", "Cucumber and crackers"]'::jsonb, '["បាយសល់ពីម្សិលមិញ ២ កែវ", "ខ្ទឹមក្រហម ២ និងខ្ទឹមស ២ កំពឹស", "ម្ទេស ១ គ្រាប់", "ទឹកស៊ីអ៊ីវផ្អែម ២ ស្លាបព្រាបាយ", "ស៊ុត ២ គ្រាប់", "ត្រសក់ និងនំក្រៀប"]'::jsonb, '["Pound the shallots, garlic and chili and fry until fragrant.", "Add the rice and sweet soy and stir-fry until hot.", "Serve with a fried egg, cucumber and crackers."]'::jsonb, '["បុកខ្ទឹមក្រហម ខ្ទឹមស និងម្ទេស លីងរហូតឈ្ងុយ។", "ដាក់បាយ និងទឹកស៊ីអ៊ីវផ្អែម ឆាឱ្យក្តៅសព្វ។", "ញ៉ាំជាមួយស៊ុតចៀន ត្រសក់ និងនំក្រៀប។"]'::jsonb),
('Gado-Gado', 'ហ្គាដូហ្គាដូ', 'Indonesian vegetable salad with egg, tofu and a peanut sauce.', 'ញាំបន្លែឥណ្ឌូនេស៊ី ជាមួយស៊ុត តៅហ៊ូ និងទឹកជ្រលក់សណ្តែកដី។', 420, 'ID', 'salad', 30, 2, 'easy', false, 51, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Gado-gado_-_Bali_2025-09-25.jpg/500px-Gado-gado_-_Bali_2025-09-25.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gado-gado_-_Bali_2025-09-25.jpg', '["Cabbage, green beans and bean sprouts", "1 potato", "2 boiled eggs", "100 g fried tofu", "4 tbsp peanut sauce", "Prawn crackers"]'::jsonb, '["ស្ពៃក្តោប សណ្តែកកួរ និងសណ្តែកបណ្តុះ", "ដំឡូងបារាំង ១ មើម", "ស៊ុតស្ងោរ ២ គ្រាប់", "តៅហ៊ូចៀន ១០០ ក្រាម", "ទឹកជ្រលក់សណ្តែកដី ៤ ស្លាបព្រាបាយ", "នំក្រៀបបង្គា"]'::jsonb, '["Blanch the vegetables and boil the potato.", "Arrange with sliced egg and tofu on a plate.", "Pour the peanut sauce over and add crackers."]'::jsonb, '["ស្រុះបន្លែ ហើយស្ងោរដំឡូង។", "រៀបជាមួយស៊ុត និងតៅហ៊ូលើចាន។", "ចាក់ទឹកជ្រលក់សណ្តែកដីពីលើ ហើយដាក់នំក្រៀប។"]'::jsonb),
('Nasi Lemak', 'បាយខ្ទិះដូងម៉ាឡេ', 'Malaysian coconut rice with sambal, egg, peanuts and crispy anchovies.', 'បាយខ្ទិះដូងម៉ាឡេស៊ី ជាមួយសាំបាល់ ស៊ុត សណ្តែកដី និងត្រីឆ្អើរស្រួយ។', 640, 'MY', 'rice', 45, 2, 'medium', false, 50, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/Nasi_Lemak_-_Roti_King_2025-09-19.jpg/500px-Nasi_Lemak_-_Roti_King_2025-09-19.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Nasi_Lemak_-_Roti_King_2025-09-19.jpg', '["1 cup rice", "200 ml coconut milk", "1 pandan leaf", "3 tbsp sambal", "2 boiled eggs", "Fried anchovies, peanuts and cucumber"]'::jsonb, '["អង្ករ ១ កែវ", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ស្លឹកតើយ ១ សន្លឹក", "សាំបាល់ ៣ ស្លាបព្រាបាយ", "ស៊ុតស្ងោរ ២ គ្រាប់", "ត្រីឆ្អើរចៀន សណ្តែកដី និងត្រសក់"]'::jsonb, '["Cook the rice with coconut milk and pandan.", "Fry the anchovies and peanuts until crisp.", "Serve the rice with sambal, egg, anchovies, peanuts and cucumber."]'::jsonb, '["ដាំបាយជាមួយខ្ទិះដូង និងស្លឹកតើយ។", "ចៀនត្រីឆ្អើរ និងសណ្តែកដីឱ្យស្រួយ។", "ញ៉ាំបាយជាមួយសាំបាល់ ស៊ុត ត្រីឆ្អើរ សណ្តែកដី និងត្រសក់។"]'::jsonb),
('Teh Tarik', 'តែទាញ', 'Frothy Malaysian milk tea, poured back and forth to cool and foam.', 'តែទឹកដោះគោម៉ាឡេស៊ីមានពពុះ ចាក់ទាញទៅមកឱ្យពពុះ។', 160, 'MY', 'drinks', 10, 2, 'easy', false, 49, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Roti_Telur_and_Teh_Tarik.jpg/500px-Roti_Telur_and_Teh_Tarik.jpg', 'Photo: Azreey, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Roti_Telur_and_Teh_Tarik.jpg', '["2 tbsp black tea leaves", "400 ml boiling water", "3 tbsp condensed milk", "2 tbsp evaporated milk"]'::jsonb, '["ស្លឹកតែខ្មៅ ២ ស្លាបព្រាបាយ", "ទឹកពុះ ៤០០ មីលីលីត្រ", "ទឹកដោះគោខាប់ ៣ ស្លាបព្រាបាយ", "ទឹកដោះគោខាប់រាវ ២ ស្លាបព្រាបាយ"]'::jsonb, '["Brew the tea strongly for 5 minutes and strain.", "Stir in both milks.", "Pour from one jug to another from a height until foamy."]'::jsonb, '["ឆុងតែឱ្យខ្លាំង ៥ នាទី ហើយចម្រោះ។", "លាយទឹកដោះគោទាំងពីរ។", "ចាក់ពីកែវមួយទៅកែវមួយពីខ្ពស់ រហូតមានពពុះ។"]'::jsonb),
('Hainanese Chicken Rice', 'បាយមាន់ហៃណាន', 'Poached chicken with fragrant ginger rice and chili sauce.', 'សាច់មាន់ស្ងោរ ជាមួយបាយខ្ញីក្រអូប និងទឹកម្ទេស។', 600, 'SG', 'rice', 60, 4, 'medium', false, 48, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Hainanese_Chicken_Rice.jpg/500px-Hainanese_Chicken_Rice.jpg', 'Photo: No machine-readable author provided. Terence assumed (based on copyright claims), CC BY 2.5, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hainanese_Chicken_Rice.jpg', '["1 whole chicken", "2 cups rice", "1 large piece ginger", "4 cloves garlic", "Chili sauce", "Cucumber"]'::jsonb, '["មាន់ ១ ក្បាល", "អង្ករ ២ កែវ", "ខ្ញី ១ ដុំធំ", "ខ្ទឹមស ៤ កំពឹស", "ទឹកម្ទេស", "ត្រសក់"]'::jsonb, '["Poach the chicken gently with ginger for 40 minutes, then chill in ice water.", "Fry the rice with garlic and ginger, then cook it in the chicken broth.", "Slice the chicken and serve with the rice, cucumber and chili sauce."]'::jsonb, '["ស្ងោរមាន់ជាមួយខ្ញីដោយភ្លើងតិច ៤០ នាទី រួចត្រាំទឹកកក។", "លីងអង្ករជាមួយខ្ទឹមស និងខ្ញី រួចដាំក្នុងទឹកស៊ុបមាន់។", "កាត់សាច់មាន់ ញ៉ាំជាមួយបាយ ត្រសក់ និងទឹកម្ទេស។"]'::jsonb),
('Kaya Toast', 'នំបុ័ងអាំងកាយ៉ា', 'Crisp toast with coconut-egg jam and butter, a Singapore breakfast.', 'នំបុ័ងអាំងស្រួយ ជាមួយយៈសាពូងស៊ុតដូង និងប៊ឺ ជាអាហារពេលព្រឹកសិង្ហបុរី។', 340, 'SG', 'snack', 10, 1, 'easy', false, 47, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Kaya_Toast_with_Coffee_%28cropped%29.jpg/500px-Kaya_Toast_with_Coffee_%28cropped%29.jpg', 'Photo: Daniel., CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Kaya_Toast_with_Coffee_(cropped).jpg', '["2 slices white bread", "2 tbsp kaya jam", "1 tbsp cold butter", "2 soft-boiled eggs", "Soy sauce and pepper"]'::jsonb, '["នំបុ័ងស ២ ចំណិត", "យៈសាពូកាយ៉ា ២ ស្លាបព្រាបាយ", "ប៊ឺត្រជាក់ ១ ស្លាបព្រាបាយ", "ស៊ុតស្ងោរទន់ ២ គ្រាប់", "ទឹកស៊ីអ៊ីវ និងម្រេច"]'::jsonb, '["Toast the bread until crisp.", "Spread with kaya and add thin slices of cold butter.", "Serve with soft eggs seasoned with soy sauce and pepper."]'::jsonb, '["អាំងនំបុ័ងឱ្យស្រួយ។", "លាបកាយ៉ា ហើយដាក់ប៊ឺត្រជាក់ចំណិតស្តើង។", "ញ៉ាំជាមួយស៊ុតទន់ ដាក់ទឹកស៊ីអ៊ីវ និងម្រេច។"]'::jsonb),
('Fish Amok', 'អាម៉ុកត្រី', 'Soft coconut fish curry steamed in banana leaf cups.', 'ការីត្រីខ្ទិះដូងទន់ៗ ចំហុយក្នុងស្លឹកចេក។', 420, 'KH', 'curry', 45, 4, 'medium', true, 100, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Fish_Amok_with_Rice.jpg/500px-Fish_Amok_with_Rice.jpg', 'Photo: sharonang, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fish_Amok_with_Rice.jpg', '["500 g white fish fillet", "200 ml coconut milk", "2 tbsp kroeung paste", "1 egg", "1 tbsp fish sauce", "Banana leaves"]'::jsonb, '["សាច់ត្រីស ៥០០ ក្រាម", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "គ្រឿង ២ ស្លាបព្រាបាយ", "ស៊ុត ១ គ្រាប់", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ស្លឹកចេក"]'::jsonb, '["Cut the fish into bite-size pieces.", "Mix kroeung paste, coconut milk, egg and fish sauce.", "Fold in the fish and spoon into banana leaf cups.", "Steam for 20 minutes until set."]'::jsonb, '["កាត់ត្រីជាដុំតូចៗ។", "លាយគ្រឿង ខ្ទិះដូង ស៊ុត និងទឹកត្រី។", "ដាក់ត្រីចូល រួចដួសដាក់ក្នុងស្លឹកចេក។", "ចំហុយ ២០ នាទី រហូតដល់ស្អិត។"]'::jsonb),
('Lok Lak', 'ឡុកឡាក់', 'Peppered stir-fried beef with a lime and black pepper dip.', 'សាច់គោឆាម្រេច ជាមួយទឹកជ្រលក់ក្រូចឆ្មាម្រេច។', 510, 'KH', 'main', 30, 2, 'easy', false, 98, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Sachko_lok_lak_-_beef_lok_lak_th%E1%BB%8Bt_b%C3%B2_l%C3%BAc_l%E1%BA%AFc_Khmer_food.jpg/500px-Sachko_lok_lak_-_beef_lok_lak_th%E1%BB%8Bt_b%C3%B2_l%C3%BAc_l%E1%BA%AFc_Khmer_food.jpg', 'Photo: Alexandersingh9, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sachko_lok_lak_-_beef_lok_lak_th%E1%BB%8Bt_b%C3%B2_l%C3%BAc_l%E1%BA%AFc_Khmer_food.jpg', '["300 g beef sirloin", "2 tbsp soy sauce", "1 tbsp oyster sauce", "3 cloves garlic", "Lettuce, tomato and onion", "1 lime and black pepper"]'::jsonb, '["សាច់គោ ៣០០ ក្រាម", "ទឹកស៊ីអ៊ីវ ២ ស្លាបព្រាបាយ", "ប្រេងខ្យង ១ ស្លាបព្រាបាយ", "ខ្ទឹមស ៣ កំពឹស", "សាឡាត់ ប៉េងប៉ោះ និងខ្ទឹមបារាំង", "ក្រូចឆ្មា ១ ផ្លែ និងម្រេចខ្មៅ"]'::jsonb, '["Cube the beef and marinate with soy, oyster sauce and garlic for 15 minutes.", "Sear on very high heat for 2 to 3 minutes.", "Serve on lettuce and tomato with the lime-pepper dip."]'::jsonb, '["កាត់សាច់គោជាដុំ ហើយប្រឡាក់ទឹកស៊ីអ៊ីវ ប្រេងខ្យង និងខ្ទឹមស ១៥ នាទី។", "ឆាលើភ្លើងខ្លាំង ២ ទៅ ៣ នាទី។", "រៀបលើសាឡាត់ និងប៉េងប៉ោះ ជាមួយទឹកជ្រលក់ក្រូចឆ្មាម្រេច។"]'::jsonb),
('Nom Banh Chok', 'នំបញ្ចុក', 'Fresh rice noodles in a green fish gravy with herbs and vegetables.', 'នំបញ្ចុកស្រស់ ជាមួយសម្លប្រហើរត្រី និងបន្លែស្រស់។', 380, 'KH', 'noodles', 60, 4, 'hard', false, 96, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Num_Banh_Chok_%28cropped%29.jpg/500px-Num_Banh_Chok_%28cropped%29.jpg', 'Photo: Thomas Wanhoff from Siem Reap, Cambodia, CC BY-SA 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Num_Banh_Chok_(cropped).jpg', '["500 g fresh rice noodles", "300 g fish", "Lemongrass, turmeric and galangal", "200 ml coconut milk", "Banana flower, cucumber and herbs"]'::jsonb, '["នំបញ្ចុកស្រស់ ៥០០ ក្រាម", "ត្រី ៣០០ ក្រាម", "ស្លឹកគ្រៃ រមៀត និងរំដេង", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ត្រយូងចេក ត្រសក់ និងជីរ"]'::jsonb, '["Boil the fish, then flake the meat.", "Pound the herbs into a paste and simmer with the fish and coconut milk.", "Pour the gravy over the noodles and top with fresh vegetables."]'::jsonb, '["ស្ងោរត្រី រួចបកយកសាច់។", "បុកគ្រឿងឱ្យម៉ត់ រួចរំងាស់ជាមួយត្រី និងខ្ទិះដូង។", "ចាក់សម្លលើនំបញ្ចុក ហើយដាក់បន្លែស្រស់ពីលើ។"]'::jsonb),
('Kuy Teav', 'គុយទាវ', 'Pork noodle soup with a clear, light broth.', 'គុយទាវសាច់ជ្រូក ជាមួយទឹកស៊ុបថ្លាស្រាល។', 350, 'KH', 'noodles', 40, 2, 'easy', false, 94, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/H%E1%BB%A7_ti%E1%BA%BFu_Nam_Vang_gi%C3%B2_2.jpg/500px-H%E1%BB%A7_ti%E1%BA%BFu_Nam_Vang_gi%C3%B2_2.jpg', 'Photo: Phương Huy (thảo luận), Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:H%E1%BB%A7_ti%E1%BA%BFu_Nam_Vang_gi%C3%B2_2.jpg', '["200 g rice noodles", "200 g pork", "500 g pork bones", "1 tbsp garlic oil", "Bean sprouts and spring onion"]'::jsonb, '["គុយទាវ ២០០ ក្រាម", "សាច់ជ្រូក ២០០ ក្រាម", "ឆ្អឹងជ្រូក ៥០០ ក្រាម", "ប្រេងខ្ទឹម ១ ស្លាបព្រាបាយ", "សណ្តែកបណ្តុះ និងស្លឹកខ្ទឹម"]'::jsonb, '["Simmer the bones for an hour for a clear broth.", "Blanch the noodles and put them in bowls.", "Top with sliced pork and pour the hot broth over."]'::jsonb, '["រំងាស់ឆ្អឹងមួយម៉ោង ដើម្បីបានទឹកស៊ុបថ្លា។", "ស្រុះគុយទាវ ហើយដាក់ក្នុងចាន។", "ដាក់សាច់ជ្រូកពីលើ រួចចាក់ទឹកស៊ុបក្តៅ។"]'::jsonb),
('Bai Sach Chrouk', 'បាយសាច់ជ្រូក', 'Grilled coconut-garlic pork over broken rice with pickles.', 'សាច់ជ្រូកអាំងខ្ទិះដូងខ្ទឹម លើបាយ ជាមួយជ្រក់។', 560, 'KH', 'rice', 30, 2, 'easy', false, 92, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Bay_sach_chrouk.jpg/500px-Bay_sach_chrouk.jpg', 'Photo: Mingjang Teang, CC BY-SA 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bay_sach_chrouk.jpg', '["300 g pork slices", "3 tbsp coconut milk", "3 cloves garlic", "1 tbsp fish sauce", "1 tbsp sugar", "2 cups cooked rice", "Pickled vegetables"]'::jsonb, '["សាច់ជ្រូកហាន់ ៣០០ ក្រាម", "ខ្ទិះដូង ៣ ស្លាបព្រាបាយ", "ខ្ទឹមស ៣ កំពឹស", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ស្ករ ១ ស្លាបព្រាបាយ", "បាយ ២ កែវ", "ជ្រក់បន្លែ"]'::jsonb, '["Marinate the pork with coconut milk, garlic, fish sauce and sugar.", "Grill until charred at the edges.", "Serve over rice with pickles."]'::jsonb, '["ប្រឡាក់សាច់ជ្រូកជាមួយខ្ទិះដូង ខ្ទឹមស ទឹកត្រី និងស្ករ។", "អាំងរហូតដល់ឆេះគែមបន្តិច។", "រៀបលើបាយ ជាមួយជ្រក់។"]'::jsonb),
('Samlor Machu Trey', 'សម្លម្ជូរត្រី', 'Sour fish soup with pineapple and tamarind.', 'សម្លម្ជូរត្រី ជាមួយម្នាស់ និងអំពិល។', 250, 'KH', 'soup', 35, 4, 'easy', false, 90, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Samlar_Machu_%287947801760%29.jpg/500px-Samlar_Machu_%287947801760%29.jpg', 'Photo: Sodanie Chea from Norwalk, Ca, United States, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Samlar_Machu_(7947801760).jpg', '["400 g fish", "2 tbsp tamarind paste", "1 cup pineapple pieces", "2 tomatoes", "Morning glory or herbs", "1 tbsp fish sauce"]'::jsonb, '["ត្រី ៤០០ ក្រាម", "ទឹកអំពិល ២ ស្លាបព្រាបាយ", "ម្នាស់ ១ កែវ", "ប៉េងប៉ោះ ២ ផ្លែ", "ត្រកួន ឬជីរ", "ទឹកត្រី ១ ស្លាបព្រាបាយ"]'::jsonb, '["Boil water with the tamarind and pineapple.", "Add the fish and tomatoes and cook for 8 minutes.", "Finish with herbs and fish sauce."]'::jsonb, '["ដាំទឹកជាមួយអំពិល និងម្នាស់។", "ដាក់ត្រី និងប៉េងប៉ោះ ស្ងោរ ៨ នាទី។", "បន្ថែមជីរ និងទឹកត្រី។"]'::jsonb),
('Khmer Chicken Curry', 'សម្លការីសាច់មាន់', 'Mild coconut curry with chicken, potato and sweet potato.', 'ការីសាច់មាន់ខ្ទិះដូងស្រាល ជាមួយដំឡូងបារាំង និងដំឡូងជ្វា។', 480, 'KH', 'curry', 50, 4, 'medium', false, 88, null, null, null, '["500 g chicken", "3 tbsp red curry kroeung", "400 ml coconut milk", "2 potatoes", "1 sweet potato", "1 onion"]'::jsonb, '["សាច់មាន់ ៥០០ ក្រាម", "គ្រឿងការីក្រហម ៣ ស្លាបព្រាបាយ", "ខ្ទិះដូង ៤០០ មីលីលីត្រ", "ដំឡូងបារាំង ២ មើម", "ដំឡូងជ្វា ១ មើម", "ខ្ទឹមបារាំង ១ មើម"]'::jsonb, '["Fry the curry paste until fragrant.", "Add the chicken and coconut milk and bring to a simmer.", "Add potato and sweet potato and cook until tender. Serve with bread or rice."]'::jsonb, '["លីងគ្រឿងការីរហូតដល់ក្លិនឈ្ងុយ។", "ដាក់សាច់មាន់ និងខ្ទិះដូង ហើយរំងាស់។", "ដាក់ដំឡូង ស្ងោររហូតដល់ទន់។ ញ៉ាំជាមួយនំបុ័ង ឬបាយ។"]'::jsonb),
('Samlor Korko', 'សម្លកកូរ', 'Thick Khmer stirred soup with pork, vegetables and toasted rice.', 'សម្លកកូរខាប់ ជាមួយសាច់ជ្រូក បន្លែ និងអង្ករលីង។', 390, 'KH', 'soup', 60, 4, 'hard', false, 86, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Samlor_Korko_Khmer_at_Peace_Cafe.jpg/500px-Samlor_Korko_Khmer_at_Peace_Cafe.jpg', 'Photo: Mx. Granger, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Samlor_Korko_Khmer_at_Peace_Cafe.jpg', '["300 g pork", "2 tbsp toasted rice powder", "Eggplant, pumpkin and green papaya", "3 tbsp kroeung paste", "1 tbsp prahok", "Herbs"]'::jsonb, '["សាច់ជ្រូក ៣០០ ក្រាម", "អង្ករលីងបុក ២ ស្លាបព្រាបាយ", "ត្រប់ ល្ពៅ និងល្ហុងខ្ចី", "គ្រឿង ៣ ស្លាបព្រាបាយ", "ប្រហុក ១ ស្លាបព្រាបាយ", "ជីរ"]'::jsonb, '["Fry the kroeung paste and prahok with the pork.", "Add water and the hard vegetables and simmer.", "Stir in the toasted rice powder to thicken, then add the herbs."]'::jsonb, '["លីងគ្រឿង និងប្រហុកជាមួយសាច់ជ្រូក។", "ចាក់ទឹក ដាក់បន្លែរឹងៗ ហើយរំងាស់។", "កូរអង្ករលីងចូលឱ្យខាប់ រួចដាក់ជីរ។"]'::jsonb),
('Num Kachay', 'នំកាឆាយ', 'Crisp fried chive cakes with a sweet and sour dip.', 'នំកាឆាយចៀនស្រួយ ជាមួយទឹកជ្រលក់ជូរផ្អែម។', 300, 'KH', 'snack', 40, 4, 'medium', false, 84, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Cambodian_deep-fried_chive_cakes.jpg/500px-Cambodian_deep-fried_chive_cakes.jpg', 'Photo: Jason Eppink from New York City, USA, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cambodian_deep-fried_chive_cakes.jpg', '["200 g rice flour", "2 tbsp tapioca starch", "1 bunch Chinese chives", "Oil for frying", "Sweet fish sauce dip"]'::jsonb, '["ម្សៅអង្ករ ២០០ ក្រាម", "ម្សៅដំឡូងមី ២ ស្លាបព្រាបាយ", "គូឆាយ ១ ចង្កោម", "ប្រេងសម្រាប់ចៀន", "ទឹកត្រីផ្អែមជ្រលក់"]'::jsonb, '["Mix the flours with warm water into a thick batter.", "Fold in the chopped chives and shape small cakes.", "Pan-fry until golden and crisp. Serve hot with the dip."]'::jsonb, '["លាយម្សៅជាមួយទឹកក្តៅឧណ្ហៗ ឱ្យខាប់។", "ដាក់គូឆាយហាន់ ហើយធ្វើជាដុំតូចៗ។", "ចៀនរហូតលឿងស្រួយ។ ញ៉ាំក្តៅៗជាមួយទឹកជ្រលក់។"]'::jsonb),
('Lemongrass Beef Stir-fry', 'ឆាគ្រឿងសាច់គោ', 'Beef stir-fried with lemongrass kroeung, chili and green beans.', 'សាច់គោឆាគ្រឿងស្លឹកគ្រៃ ជាមួយម្ទេស និងសណ្តែកកួរ។', 430, 'KH', 'main', 25, 2, 'easy', false, 82, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Cha_kroeung.jpg/500px-Cha_kroeung.jpg', 'Photo: Thomas Wanhoff, CC BY-SA 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cha_kroeung.jpg', '["250 g beef", "2 tbsp lemongrass kroeung", "1 chili", "100 g green beans", "1 tbsp fish sauce", "1 tbsp oil"]'::jsonb, '["សាច់គោ ២៥០ ក្រាម", "គ្រឿងស្លឹកគ្រៃ ២ ស្លាបព្រាបាយ", "ម្ទេស ១ គ្រាប់", "សណ្តែកកួរ ១០០ ក្រាម", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ប្រេង ១ ស្លាបព្រាបាយ"]'::jsonb, '["Slice the beef thinly.", "Fry the kroeung and chili in oil until fragrant.", "Add beef, beans and fish sauce and stir on high heat for 3 minutes."]'::jsonb, '["ហាន់សាច់គោឱ្យស្តើង។", "លីងគ្រឿង និងម្ទេសក្នុងប្រេងរហូតឈ្ងុយ។", "ដាក់សាច់គោ សណ្តែកកួរ និងទឹកត្រី ឆាលើភ្លើងខ្លាំង ៣ នាទី។"]'::jsonb),
('Chicken Fried Rice', 'បាយឆាសាច់មាន់', 'Quick wok-fried rice with chicken, egg and tomato.', 'បាយឆារហ័ស ជាមួយសាច់មាន់ ស៊ុត និងប៉េងប៉ោះ។', 520, 'KH', 'rice', 20, 2, 'easy', false, 80, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Hongkong_Fried_Rice_2.jpg/500px-Hongkong_Fried_Rice_2.jpg', 'Photo: Bajinra, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Hongkong_Fried_Rice_2.jpg', '["2 cups cooked rice", "1 chicken breast", "2 eggs", "1 tomato", "1 tbsp fish sauce", "1 tbsp oil"]'::jsonb, '["បាយ ២ កែវ", "សាច់ទ្រូងមាន់ ១ ដុំ", "ស៊ុត ២ គ្រាប់", "ប៉េងប៉ោះ ១ ផ្លែ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ប្រេង ១ ស្លាបព្រាបាយ"]'::jsonb, '["Fry the diced chicken until cooked.", "Scramble the eggs in the wok.", "Add rice, tomato and fish sauce and stir-fry for 3 minutes."]'::jsonb, '["ឆាសាច់មាន់ហាន់ដុំឱ្យឆ្អិន។", "វាយស៊ុតក្នុងខ្ទះ។", "ដាក់បាយ ប៉េងប៉ោះ និងទឹកត្រី ឆា ៣ នាទី។"]'::jsonb),
('Prahok Ktis', 'ប្រហុកខ្ទិះ', 'Creamy pork and prahok dip in coconut milk, eaten with fresh vegetables.', 'ប្រហុកខ្ទិះសាច់ជ្រូក ខ្ទិះដូង ញ៉ាំជាមួយបន្លែស្រស់។', 450, 'KH', 'main', 30, 4, 'medium', false, 79, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Prahok_ktiss.jpg/500px-Prahok_ktiss.jpg', 'Photo: Timothy Vollmer, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Prahok_ktiss.jpg', '["200 g minced pork", "2 tbsp prahok", "300 ml coconut milk", "2 tbsp kroeung paste", "3 pea eggplants", "Fresh vegetables to dip"]'::jsonb, '["សាច់ជ្រូកចិញ្ច្រាំ ២០០ ក្រាម", "ប្រហុក ២ ស្លាបព្រាបាយ", "ខ្ទិះដូង ៣០០ មីលីលីត្រ", "គ្រឿង ២ ស្លាបព្រាបាយ", "ត្រប់ពុត ៣ គ្រាប់", "បន្លែស្រស់សម្រាប់ជ្រលក់"]'::jsonb, '["Simmer the coconut milk with the kroeung paste.", "Add the pork and prahok and cook, stirring, for 10 minutes.", "Add the pea eggplants and serve with fresh vegetables."]'::jsonb, '["រំងាស់ខ្ទិះដូងជាមួយគ្រឿង។", "ដាក់សាច់ជ្រូក និងប្រហុក កូរ ១០ នាទី។", "ដាក់ត្រប់ពុត ហើយញ៉ាំជាមួយបន្លែស្រស់។"]'::jsonb),
('Kdam Chhar', 'ក្តាមឆាម្រេចខ្ចី', 'Crab stir-fried with fresh Kampot green peppercorns.', 'ក្តាមឆាជាមួយម្រេចខ្ចីកំពត។', 330, 'KH', 'main', 30, 2, 'medium', true, 78, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Fried_crab_with_green_pepper.jpg/500px-Fried_crab_with_green_pepper.jpg', 'Photo: eric yeargan, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fried_crab_with_green_pepper.jpg', '["2 blue crabs", "3 stems fresh green peppercorns", "3 cloves garlic", "1 tbsp oyster sauce", "1 tbsp fish sauce", "1 tbsp oil"]'::jsonb, '["ក្តាមសេះ ២ ក្បាល", "ម្រេចខ្ចី ៣ ចង្កោម", "ខ្ទឹមស ៣ កំពឹស", "ប្រេងខ្យង ១ ស្លាបព្រាបាយ", "ទឹកត្រី ១ ស្លាបព្រាបាយ", "ប្រេង ១ ស្លាបព្រាបាយ"]'::jsonb, '["Clean the crabs and cut them in half.", "Fry the garlic, then add the crab and stir for 5 minutes.", "Add the peppercorns and sauces and cook for 3 more minutes."]'::jsonb, '["លាងក្តាមឱ្យស្អាត ហើយកាត់ពាក់កណ្តាល។", "លីងខ្ទឹមស រួចដាក់ក្តាម ឆា ៥ នាទី។", "ដាក់ម្រេចខ្ចី និងទឹកជ្រលក់ ឆា ៣ នាទីទៀត។"]'::jsonb),
('Num Pang', 'នំបុ័ងសាច់', 'Khmer baguette sandwich with pâté, meat, pickles and herbs.', 'នំបុ័ងខ្មែរ ជាមួយប៉ាតេ សាច់ ជ្រក់ និងជីរ។', 480, 'KH', 'snack', 15, 1, 'easy', true, 77, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Catfish_peppercorn_num_pang.jpg/500px-Catfish_peppercorn_num_pang.jpg', 'Photo: Krista, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Catfish_peppercorn_num_pang.jpg', '["1 baguette", "2 tbsp pâté", "80 g grilled pork or cold cuts", "Pickled carrot and papaya", "Cucumber and cilantro", "Chili sauce"]'::jsonb, '["នំបុ័ង ១ ដើម", "ប៉ាតេ ២ ស្លាបព្រាបាយ", "សាច់ជ្រូកអាំង ឬសាច់ក្រក ៨០ ក្រាម", "ជ្រក់ការ៉ុត និងល្ហុង", "ត្រសក់ និងជីវ៉ាន់ស៊ុយ", "ទឹកម្ទេស"]'::jsonb, '["Warm the baguette and slice it open.", "Spread with pâté and add the meat.", "Fill with pickles, cucumber and herbs, and add chili sauce."]'::jsonb, '["កម្តៅនំបុ័ង ហើយវះចំហ។", "លាបប៉ាតេ ហើយដាក់សាច់។", "ដាក់ជ្រក់ ត្រសក់ ជីរ និងទឹកម្ទេស។"]'::jsonb),
('Samlor Machu Youn', 'សម្លម្ជូរយួន', 'Sweet and sour fish soup with pineapple, tomato and herbs.', 'សម្លម្ជូរយួនជូរផ្អែម ជាមួយម្នាស់ ប៉េងប៉ោះ និងជីរ។', 220, 'KH', 'soup', 35, 4, 'easy', false, 76, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Canh_chua_c%C3%A1_l%C3%B3c_%E1%BB%9F_Th%E1%BB%A7y_Tr%C3%BAc_Qu%C3%A1n%2C_%C4%91%C6%B0%E1%BB%9Dng_Nguy%E1%BB%85n_Nh%E1%BB%AF_L%C3%A3m_%281%29.jpg/500px-Canh_chua_c%C3%A1_l%C3%B3c_%E1%BB%9F_Th%E1%BB%A7y_Tr%C3%BAc_Qu%C3%A1n%2C_%C4%91%C6%B0%E1%BB%9Dng_Nguy%E1%BB%85n_Nh%E1%BB%AF_L%C3%A3m_%281%29.jpg', 'Photo: Phương Huy (thảo luận), Public domain, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Canh_chua_c%C3%A1_l%C3%B3c_%E1%BB%9F_Th%E1%BB%A7y_Tr%C3%BAc_Qu%C3%A1n,_%C4%91%C6%B0%E1%BB%9Dng_Nguy%E1%BB%85n_Nh%E1%BB%AF_L%C3%A3m_(1).jpg', '["400 g catfish", "2 tbsp tamarind paste", "1 cup pineapple", "2 tomatoes", "Bean sprouts and lotus stems", "Rice paddy herb and fried garlic"]'::jsonb, '["ត្រីអណ្តែង ៤០០ ក្រាម", "ទឹកអំពិល ២ ស្លាបព្រាបាយ", "ម្នាស់ ១ កែវ", "ប៉េងប៉ោះ ២ ផ្លែ", "សណ្តែកបណ្តុះ និងក្រអៅឈូក", "ម្អម និងខ្ទឹមចៀន"]'::jsonb, '["Boil water with tamarind, pineapple and a little sugar.", "Add the fish and tomatoes and cook for 8 minutes.", "Add the vegetables, then top with herbs and fried garlic."]'::jsonb, '["ដាំទឹកជាមួយអំពិល ម្នាស់ និងស្ករបន្តិច។", "ដាក់ត្រី និងប៉េងប៉ោះ ស្ងោរ ៨ នាទី។", "ដាក់បន្លែ រួចរោយម្អម និងខ្ទឹមចៀន។"]'::jsonb),
('Num Ansom', 'នំអន្សម', 'Sticky rice cake with banana, wrapped in banana leaf and boiled.', 'នំអន្សមចេក ធ្វើពីបាយដំណើប ខ្ចប់ស្លឹកចេក ហើយស្ងោរ។', 320, 'KH', 'sweet', 120, 6, 'hard', false, 75, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Num_ansom_chek_Khmer_Cambodian_dessert_rice_cake.jpg/500px-Num_ansom_chek_Khmer_Cambodian_dessert_rice_cake.jpg', 'Photo: MoonsMoon, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Num_ansom_chek_Khmer_Cambodian_dessert_rice_cake.jpg', '["500 g sticky rice", "200 ml coconut milk", "3 ripe bananas", "1 tsp salt", "2 tbsp sugar", "Banana leaves and string"]'::jsonb, '["អង្ករដំណើប ៥០០ ក្រាម", "ខ្ទិះដូង ២០០ មីលីលីត្រ", "ចេកទុំ ៣ ផ្លែ", "អំបិល ១ ស្លាបព្រាកាហ្វេ", "ស្ករ ២ ស្លាបព្រាបាយ", "ស្លឹកចេក និងខ្សែ"]'::jsonb, '["Soak the sticky rice for 4 hours, then mix with coconut milk, salt and sugar.", "Wrap the rice around a banana in banana leaves and tie tightly.", "Boil for 90 minutes and cool before slicing."]'::jsonb, '["ត្រាំអង្ករដំណើប ៤ ម៉ោង រួចលាយខ្ទិះដូង អំបិល និងស្ករ។", "ខ្ចប់អង្ករព័ទ្ធជុំវិញចេក ក្នុងស្លឹកចេក ហើយចងឱ្យណែន។", "ស្ងោរ ៩០ នាទី ទុកឱ្យត្រជាក់ ទើបកាត់។"]'::jsonb),
('Tuk Ampov', 'ទឹកអំពៅ', 'Fresh-pressed sugarcane juice with a squeeze of lime over ice.', 'ទឹកអំពៅកិនស្រស់ ជាមួយក្រូចឆ្មាបន្តិច និងទឹកកក។', 180, 'KH', 'drinks', 10, 2, 'easy', false, 74, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Sugar_cane_juice_in_Phnom_Penh_4.jpg/500px-Sugar_cane_juice_in_Phnom_Penh_4.jpg', 'Photo: Mx. Granger, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sugar_cane_juice_in_Phnom_Penh_4.jpg', '["4 sticks peeled sugarcane", "1 calamansi or lime", "Ice"]'::jsonb, '["អំពៅចិតសំបក ៤ ដើម", "ក្រូចឆ្មា ១ ផ្លែ", "ទឹកកក"]'::jsonb, '["Press the sugarcane through a juicer.", "Add a squeeze of lime.", "Pour over ice and drink fresh."]'::jsonb, '["កិនអំពៅយកទឹក។", "ច្របាច់ក្រូចឆ្មាបន្តិច។", "ចាក់លើទឹកកក ហើយផឹកភ្លាមៗ។"]'::jsonb),
('Pizza Margherita', 'ភីហ្សាម៉ាហ្គារីតា', 'Neapolitan pizza with tomato, mozzarella and fresh basil.', 'ភីហ្សាណាប៉ូលី ជាមួយប៉េងប៉ោះ ឈីសម៉ូហ្សារ៉ែឡា និងជីរនាងវង។', 700, 'IT', 'main', 90, 2, 'medium', false, 46, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Margherita_pizza_on_plate_2.jpg/500px-Margherita_pizza_on_plate_2.jpg', 'Photo: Shisma, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Margherita_pizza_on_plate_2.jpg', '["250 g pizza dough", "100 g crushed tomatoes", "125 g mozzarella", "Fresh basil", "1 tbsp olive oil"]'::jsonb, '["ម្សៅភីហ្សា ២៥០ ក្រាម", "ប៉េងប៉ោះកិន ១០០ ក្រាម", "ឈីសម៉ូហ្សារ៉ែឡា ១២៥ ក្រាម", "ជីរនាងវងស្រស់", "ប្រេងអូលីវ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Stretch the dough into a thin round.", "Spread with tomato and add torn mozzarella.", "Bake at the highest oven heat for 8 to 10 minutes, then add basil and oil."]'::jsonb, '["ពន្លាតម្សៅជារង្វង់ស្តើង។", "លាបប៉េងប៉ោះ ហើយដាក់ឈីសហែក។", "ដុតក្នុងឡកម្តៅខ្ពស់បំផុត ៨ ទៅ ១០ នាទី រួចដាក់ជីរនាងវង និងប្រេង។"]'::jsonb),
('Tiramisu', 'ធីរ៉ាមីស៊ូ', 'Italian layered dessert of coffee-soaked biscuits and mascarpone cream.', 'បង្អែមអ៊ីតាលីជាន់ៗ នំត្រាំកាហ្វេ និងក្រែមម៉ាស្ការផូន។', 450, 'IT', 'sweet', 30, 6, 'medium', false, 45, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Tiramisu_at_Italian_restaurant_in_Japan.jpg/500px-Tiramisu_at_Italian_restaurant_in_Japan.jpg', 'Photo: Syced, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tiramisu_at_Italian_restaurant_in_Japan.jpg', '["250 g mascarpone", "3 eggs", "80 g sugar", "200 g ladyfinger biscuits", "250 ml strong coffee", "Cocoa powder"]'::jsonb, '["ឈីសម៉ាស្ការផូន ២៥០ ក្រាម", "ស៊ុត ៣ គ្រាប់", "ស្ករ ៨០ ក្រាម", "នំស្ពុងស្រួយ ២០០ ក្រាម", "កាហ្វេខ្លាំង ២៥០ មីលីលីត្រ", "ម្សៅកាកាវ"]'::jsonb, '["Beat the yolks with sugar, then fold in mascarpone and whipped whites.", "Dip the biscuits in coffee and layer with the cream.", "Chill for at least 4 hours and dust with cocoa."]'::jsonb, '["វាយស្នូលស៊ុតជាមួយស្ករ រួចលាយម៉ាស្ការផូន និងសស៊ុតវាយ។", "ជ្រលក់នំក្នុងកាហ្វេ ហើយរៀបជាជាន់ជាមួយក្រែម។", "ដាក់ទូទឹកកកយ៉ាងតិច ៤ ម៉ោង ហើយរោយម្សៅកាកាវ។"]'::jsonb),
('Ratatouille', 'រ៉ាតាទូយ', 'Provençal stew of eggplant, zucchini, peppers and tomato in olive oil.', 'បន្លែខបែបប្រូវ៉ង់ស ជាមួយត្រប់ ត្រសក់បារាំង ម្ទេសប្លោក និងប៉េងប៉ោះ។', 220, 'FR', 'main', 60, 4, 'easy', false, 44, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Ratatouille.jpg/500px-Ratatouille.jpg', 'Photo: Marcus Guimarães, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Ratatouille.jpg', '["1 eggplant", "2 zucchini", "2 bell peppers", "4 tomatoes", "1 onion and 3 cloves garlic", "3 tbsp olive oil"]'::jsonb, '["ត្រប់ ១ ផ្លែ", "ត្រសក់បារាំង ២ ផ្លែ", "ម្ទេសប្លោក ២ ផ្លែ", "ប៉េងប៉ោះ ៤ ផ្លែ", "ខ្ទឹមបារាំង ១ និងខ្ទឹមស ៣ កំពឹស", "ប្រេងអូលីវ ៣ ស្លាបព្រាបាយ"]'::jsonb, '["Cut all the vegetables into chunks.", "Fry the onion and garlic, then add peppers, eggplant and zucchini.", "Add tomatoes and simmer gently for 40 minutes."]'::jsonb, '["កាត់បន្លែទាំងអស់ជាដុំ។", "លីងខ្ទឹមបារាំង និងខ្ទឹមស រួចដាក់ម្ទេសប្លោក ត្រប់ និងត្រសក់។", "ដាក់ប៉េងប៉ោះ ហើយខដោយភ្លើងតិច ៤០ នាទី។"]'::jsonb),
('Crème Brûlée', 'ក្រែមប្រ៊ុយឡេ', 'Vanilla custard with a crackly caramelised sugar top.', 'ក្រែមស៊ុតវ៉ានីឡា មានស្ករដុតស្រួយពីលើ។', 400, 'FR', 'sweet', 60, 4, 'medium', false, 43, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Cr%C3%A8me_br%C3%BBl%C3%A9e_at_restaurant_in_Zushi.jpg/500px-Cr%C3%A8me_br%C3%BBl%C3%A9e_at_restaurant_in_Zushi.jpg', 'Photo: Syced, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cr%C3%A8me_br%C3%BBl%C3%A9e_at_restaurant_in_Zushi.jpg', '["500 ml cream", "5 egg yolks", "80 g sugar", "1 vanilla pod", "4 tbsp sugar for the top"]'::jsonb, '["ក្រែម ៥០០ មីលីលីត្រ", "ស្នូលស៊ុត ៥ គ្រាប់", "ស្ករ ៨០ ក្រាម", "វ៉ានីឡា ១ ដើម", "ស្ករ ៤ ស្លាបព្រាបាយសម្រាប់ដុតពីលើ"]'::jsonb, '["Warm the cream with vanilla, then whisk into the yolks and sugar.", "Bake in small dishes in a water bath at 150 °C for 35 minutes.", "Chill, sprinkle with sugar and caramelise with a torch."]'::jsonb, '["កម្តៅក្រែមជាមួយវ៉ានីឡា រួចវាយលាយស្នូលស៊ុត និងស្ករ។", "ដុតក្នុងចានតូចៗ ដាក់ក្នុងថាសទឹក ១៥០ អង្សា ៣៥ នាទី។", "ទុកឱ្យត្រជាក់ រោយស្ករ ហើយដុតឱ្យស្ករឡើងពណ៌។"]'::jsonb),
('Paella', 'ប៉ាអេយ៉ា', 'Spanish saffron rice cooked in a wide pan with seafood.', 'បាយអេស្ប៉ាញដាក់សាហ្វ្រង់ ដាំក្នុងខ្ទះធំ ជាមួយគ្រឿងសមុទ្រ។', 580, 'ES', 'rice', 60, 4, 'hard', false, 42, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Paella_valenciana%2C_Mazatl%C3%A1n%2C_25_de_abril_de_2023.jpg/500px-Paella_valenciana%2C_Mazatl%C3%A1n%2C_25_de_abril_de_2023.jpg', 'Photo: El Nuevo Doge, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paella_valenciana,_Mazatl%C3%A1n,_25_de_abril_de_2023.jpg', '["300 g paella rice", "1 litre fish stock", "300 g mixed seafood", "1 pinch saffron", "1 tomato and 1 bell pepper", "3 tbsp olive oil"]'::jsonb, '["អង្ករប៉ាអេយ៉ា ៣០០ ក្រាម", "ទឹកស៊ុបត្រី ១ លីត្រ", "គ្រឿងសមុទ្រចម្រុះ ៣០០ ក្រាម", "សាហ្វ្រង់ បន្តិច", "ប៉េងប៉ោះ ១ និងម្ទេសប្លោក ១", "ប្រេងអូលីវ ៣ ស្លាបព្រាបាយ"]'::jsonb, '["Fry the pepper and grated tomato in olive oil.", "Add the rice, stock and saffron and spread evenly. Do not stir.", "Add the seafood on top and cook until the rice is tender and crisp at the bottom."]'::jsonb, '["ឆាម្ទេសប្លោក និងប៉េងប៉ោះកោស ក្នុងប្រេងអូលីវ។", "ដាក់អង្ករ ទឹកស៊ុប និងសាហ្វ្រង់ ពង្រាយឱ្យស្មើ។ កុំកូរ។", "ដាក់គ្រឿងសមុទ្រពីលើ ដាំរហូតបាយទន់ និងក្រៀមបាត។"]'::jsonb),
('Gazpacho', 'ស៊ុបត្រជាក់ហ្គាសប៉ាឆូ', 'Chilled Andalusian tomato and cucumber soup.', 'ស៊ុបប៉េងប៉ោះ និងត្រសក់ត្រជាក់ បែបអង់ដាលូស៊ី។', 150, 'ES', 'soup', 15, 4, 'easy', false, 41, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Gazpacho_con_su_guarnici%C3%B3n_-_jlastras.jpg/500px-Gazpacho_con_su_guarnici%C3%B3n_-_jlastras.jpg', 'Photo: Javier Lastras from España/Spain, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Gazpacho_con_su_guarnici%C3%B3n_-_jlastras.jpg', '["1 kg ripe tomatoes", "1 cucumber", "1 green pepper", "1 clove garlic", "3 tbsp olive oil", "1 tbsp vinegar"]'::jsonb, '["ប៉េងប៉ោះទុំ ១ គីឡូក្រាម", "ត្រសក់ ១ ផ្លែ", "ម្ទេសប្លោកបៃតង ១ ផ្លែ", "ខ្ទឹមស ១ កំពឹស", "ប្រេងអូលីវ ៣ ស្លាបព្រាបាយ", "ទឹកខ្មេះ ១ ស្លាបព្រាបាយ"]'::jsonb, '["Chop the vegetables roughly.", "Blend with olive oil, vinegar and salt until smooth.", "Chill for 2 hours and top with diced cucumber."]'::jsonb, '["កាត់បន្លែជាដុំធំៗ។", "ក្រឡុកជាមួយប្រេងអូលីវ ទឹកខ្មេះ និងអំបិលឱ្យម៉ត់។", "ដាក់ទូទឹកកក ២ ម៉ោង ហើយដាក់ត្រសក់ហាន់ពីលើ។"]'::jsonb),
('Pancakes', 'នំផេនខេក', 'Fluffy American pancakes served with honey or syrup.', 'នំផេនខេកអាមេរិកទន់ហើម ញ៉ាំជាមួយទឹកឃ្មុំ ឬទឹកស្ករ។', 430, 'US', 'sweet', 20, 2, 'easy', false, 40, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg/500px-Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg', 'Photo: Mae Mu, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Foodiesfeed.com_pouring-honey-on-pancakes-with-walnuts.jpg', '["150 g flour", "2 tsp baking powder", "1 egg", "200 ml milk", "1 tbsp sugar", "Butter and honey"]'::jsonb, '["ម្សៅ ១៥០ ក្រាម", "ម្សៅដំបែ ២ ស្លាបព្រាកាហ្វេ", "ស៊ុត ១ គ្រាប់", "ទឹកដោះគោ ២០០ មីលីលីត្រ", "ស្ករ ១ ស្លាបព្រាបាយ", "ប៊ឺ និងទឹកឃ្មុំ"]'::jsonb, '["Whisk the dry ingredients, then add egg and milk.", "Cook small rounds in a buttered pan until bubbles form, then flip.", "Stack and drizzle with honey."]'::jsonb, '["លាយគ្រឿងស្ងួត រួចដាក់ស៊ុត និងទឹកដោះគោ។", "ចៀនជារង្វង់តូចៗក្នុងខ្ទះលាបប៊ឺ រហូតមានពពុះ ហើយត្រឡប់។", "តម្រៀបជាជង់ ហើយស្រោចទឹកឃ្មុំ។"]'::jsonb),
('Cheeseburger', 'ឈីសប៊ឺហ្គឺ', 'Grilled beef burger with melted cheese, lettuce and tomato.', 'ប៊ឺហ្គឺសាច់គោអាំង ជាមួយឈីសរលាយ សាឡាត់ និងប៉េងប៉ោះ។', 750, 'US', 'main', 20, 2, 'easy', false, 39, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Cheeseburger_2.jpg/500px-Cheeseburger_2.jpg', 'Photo: Kurtkaiser, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Cheeseburger_2.jpg', '["300 g ground beef", "2 burger buns", "2 slices cheese", "Lettuce and tomato", "Pickles", "Ketchup and mustard"]'::jsonb, '["សាច់គោចិញ្ច្រាំ ៣០០ ក្រាម", "នំបុ័ងប៊ឺហ្គឺ ២", "ឈីស ២ សន្លឹក", "សាឡាត់ និងប៉េងប៉ោះ", "ត្រសក់ជ្រក់", "ទឹកប៉េងប៉ោះ និងទឹកមូស្តាត"]'::jsonb, '["Shape the beef into two patties and season with salt and pepper.", "Grill for 3 minutes per side and add cheese to melt.", "Build in toasted buns with lettuce, tomato, pickles and sauces."]'::jsonb, '["ធ្វើសាច់គោជាដុំសំប៉ែតពីរ ប្រឡាក់អំបិល និងម្រេច។", "អាំងម្ខាង ៣ នាទី ហើយដាក់ឈីសឱ្យរលាយ។", "ដាក់ក្នុងនំបុ័ងអាំង ជាមួយសាឡាត់ ប៉េងប៉ោះ ត្រសក់ជ្រក់ និងទឹកជ្រលក់។"]'::jsonb),
('Guacamole', 'ក្វាកាម៉ូលេ', 'Mexican avocado dip with lime, onion and cilantro, served with chips.', 'ទឹកជ្រលក់ផ្លែបឺម៉ិកស៊ិក ជាមួយក្រូចឆ្មា ខ្ទឹមបារាំង និងជីវ៉ាន់ស៊ុយ។', 230, 'MX', 'snack', 10, 4, 'easy', false, 38, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Guacamole_and_chips_-_Stierch.jpg/500px-Guacamole_and_chips_-_Stierch.jpg', 'Photo: Missvain, CC BY 4.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Guacamole_and_chips_-_Stierch.jpg', '["3 ripe avocados", "1 lime", "1 small onion", "1 tomato", "Cilantro", "Tortilla chips"]'::jsonb, '["ផ្លែបឺទុំ ៣ ផ្លែ", "ក្រូចឆ្មា ១ ផ្លែ", "ខ្ទឹមបារាំងតូច ១ មើម", "ប៉េងប៉ោះ ១ ផ្លែ", "ជីវ៉ាន់ស៊ុយ", "នំក្រៀបតតុកស៊ី"]'::jsonb, '["Mash the avocados with lime juice and salt.", "Stir in the chopped onion, tomato and cilantro.", "Serve straight away with tortilla chips."]'::jsonb, '["កិនផ្លែបឺជាមួយទឹកក្រូចឆ្មា និងអំបិល។", "លាយខ្ទឹមបារាំង ប៉េងប៉ោះ និងជីវ៉ាន់ស៊ុយហាន់។", "ញ៉ាំភ្លាមជាមួយនំក្រៀប។"]'::jsonb),
('Horchata', 'អរឆាតា', 'Sweet Mexican rice and cinnamon drink served over ice.', 'ភេសជ្ជៈអង្ករ និងសំបកឈើក្រអូបម៉ិកស៊ិកផ្អែម ចាក់លើទឹកកក។', 200, 'MX', 'drinks', 15, 4, 'easy', false, 37, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Horchata%2C_my_drink_of_choice_in_Mexico_-_Merida_Yucatan_21_March_2021.jpg/500px-Horchata%2C_my_drink_of_choice_in_Mexico_-_Merida_Yucatan_21_March_2021.jpg', 'Photo: Sharon Hahn Darlin, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Horchata,_my_drink_of_choice_in_Mexico_-_Merida_Yucatan_21_March_2021.jpg', '["150 g white rice", "1 cinnamon stick", "1 litre water", "100 g sugar", "100 ml milk", "Ice"]'::jsonb, '["អង្ករស ១៥០ ក្រាម", "សំបកឈើក្រអូប ១ ដើម", "ទឹក ១ លីត្រ", "ស្ករ ១០០ ក្រាម", "ទឹកដោះគោ ១០០ មីលីលីត្រ", "ទឹកកក"]'::jsonb, '["Soak the rice and cinnamon in water overnight.", "Blend well and strain through a cloth.", "Stir in sugar and milk and serve over ice."]'::jsonb, '["ត្រាំអង្ករ និងសំបកឈើក្រអូបក្នុងទឹកមួយយប់។", "ក្រឡុកឱ្យម៉ត់ ហើយចម្រោះតាមក្រណាត់។", "លាយស្ករ និងទឹកដោះគោ ហើយចាក់លើទឹកកក។"]'::jsonb),
('Lentil Soup', 'ស៊ុបសណ្តែកលីនទីល', 'Smooth Turkish red lentil soup with a squeeze of lemon.', 'ស៊ុបសណ្តែកលីនទីលក្រហមតួកគីម៉ត់ ច្របាច់ក្រូចឆ្មាបន្តិច។', 260, 'TR', 'soup', 35, 4, 'easy', false, 36, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg/500px-Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg', '["200 g red lentils", "1 onion", "1 carrot", "1 tbsp tomato paste", "1 litre stock", "1 lemon"]'::jsonb, '["សណ្តែកលីនទីលក្រហម ២០០ ក្រាម", "ខ្ទឹមបារាំង ១ មើម", "ការ៉ុត ១ មើម", "ប៉េងប៉ោះខាប់ ១ ស្លាបព្រាបាយ", "ទឹកស៊ុប ១ លីត្រ", "ក្រូចឆ្មា ១ ផ្លែ"]'::jsonb, '["Fry the onion, carrot and tomato paste.", "Add the lentils and stock and simmer for 25 minutes.", "Blend until smooth and serve with lemon."]'::jsonb, '["ឆាខ្ទឹមបារាំង ការ៉ុត និងប៉េងប៉ោះខាប់។", "ដាក់សណ្តែក និងទឹកស៊ុប រំងាស់ ២៥ នាទី។", "ក្រឡុកឱ្យម៉ត់ ហើយញ៉ាំជាមួយក្រូចឆ្មា។"]'::jsonb),
('Baklava', 'បាក្លាវ៉ា', 'Layers of crisp filo pastry with nuts, soaked in sweet syrup.', 'នំស្រទាប់ស្តើងៗស្រួយ ជាមួយគ្រាប់ធញ្ញជាតិ ត្រាំទឹកស្ករ។', 420, 'TR', 'sweet', 90, 12, 'hard', false, 35, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Baklava_in_pan.jpg/500px-Baklava_in_pan.jpg', 'Photo: Punker1999, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Baklava_in_pan.jpg', '["500 g filo pastry", "250 g butter, melted", "300 g chopped pistachios or walnuts", "300 g sugar", "200 ml water", "1 tbsp lemon juice"]'::jsonb, '["ស្លឹកម្សៅហ្វីឡូ ៥០០ ក្រាម", "ប៊ឺរលាយ ២៥០ ក្រាម", "គ្រាប់ពីស្តាស ឬវ៉ាល់ណាត់ហាន់ ៣០០ ក្រាម", "ស្ករ ៣០០ ក្រាម", "ទឹក ២០០ មីលីលីត្រ", "ទឹកក្រូចឆ្មា ១ ស្លាបព្រាបាយ"]'::jsonb, '["Layer buttered filo sheets in a tray, with nuts in the middle.", "Cut into diamonds and bake at 170 °C for 45 minutes.", "Pour cooled syrup over the hot baklava and rest for 4 hours."]'::jsonb, '["រៀបស្លឹកហ្វីឡូលាបប៊ឺក្នុងថាស ដាក់គ្រាប់នៅកណ្តាល។", "កាត់ជារាងពេជ្រ ហើយដុត ១៧០ អង្សា ៤៥ នាទី។", "ចាក់ទឹកស្ករត្រជាក់លើនំក្តៅ ហើយទុក ៤ ម៉ោង។"]'::jsonb),
('Greek Salad', 'សាឡាត់ក្រិក', 'Tomato, cucumber, olives and feta with olive oil and oregano.', 'ប៉េងប៉ោះ ត្រសក់ ផ្លែអូលីវ និងឈីសហ្វេតា ជាមួយប្រេងអូលីវ។', 280, 'GR', 'salad', 10, 2, 'easy', false, 34, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Greek_Salad_Choriatiki.jpg/500px-Greek_Salad_Choriatiki.jpg', 'Photo: https://www.flickr.com/photos/zone41/, CC BY 2.0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Greek_Salad_Choriatiki.jpg', '["3 tomatoes", "1 cucumber", "1 red onion", "100 g feta cheese", "10 olives", "2 tbsp olive oil and oregano"]'::jsonb, '["ប៉េងប៉ោះ ៣ ផ្លែ", "ត្រសក់ ១ ផ្លែ", "ខ្ទឹមបារាំងក្រហម ១ មើម", "ឈីសហ្វេតា ១០០ ក្រាម", "ផ្លែអូលីវ ១០ គ្រាប់", "ប្រេងអូលីវ ២ ស្លាបព្រាបាយ និងអូរេហ្គាណូ"]'::jsonb, '["Cut the tomatoes and cucumber into chunks and slice the onion.", "Add the olives and a block of feta on top.", "Drizzle with olive oil and sprinkle with oregano."]'::jsonb, '["កាត់ប៉េងប៉ោះ និងត្រសក់ជាដុំ ហើយហាន់ខ្ទឹមបារាំង។", "ដាក់ផ្លែអូលីវ និងឈីសហ្វេតាមួយដុំពីលើ។", "ស្រោចប្រេងអូលីវ ហើយរោយអូរេហ្គាណូ។"]'::jsonb),
('Moussaka', 'មូសាកា', 'Baked layers of eggplant, spiced meat sauce and creamy white sauce.', 'ត្រប់ ទឹកសាច់គ្រឿងទេស និងទឹកក្រែមស ដុតជាស្រទាប់ៗ។', 620, 'GR', 'main', 90, 6, 'hard', false, 33, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Meat_Moussaka_-_Kouzina%2C_Brighton_2023-11-24.jpg/500px-Meat_Moussaka_-_Kouzina%2C_Brighton_2023-11-24.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Meat_Moussaka_-_Kouzina,_Brighton_2023-11-24.jpg', '["3 eggplants", "500 g minced lamb or beef", "400 g crushed tomatoes", "1 onion", "1 tsp cinnamon", "500 ml white sauce"]'::jsonb, '["ត្រប់ ៣ ផ្លែ", "សាច់ចៀម ឬសាច់គោចិញ្ច្រាំ ៥០០ ក្រាម", "ប៉េងប៉ោះកិន ៤០០ ក្រាម", "ខ្ទឹមបារាំង ១ មើម", "ម្សៅសំបកឈើក្រអូប ១ ស្លាបព្រាកាហ្វេ", "ទឹកក្រែមស ៥០០ មីលីលីត្រ"]'::jsonb, '["Slice and fry or roast the eggplant.", "Cook the meat with onion, tomatoes and cinnamon.", "Layer eggplant and meat, top with white sauce and bake at 180 °C for 45 minutes."]'::jsonb, '["កាត់ត្រប់ ហើយចៀន ឬដុត។", "ឆាសាច់ជាមួយខ្ទឹមបារាំង ប៉េងប៉ោះ និងសំបកឈើក្រអូប។", "រៀបត្រប់ និងសាច់ជាស្រទាប់ ដាក់ទឹកក្រែមសពីលើ ហើយដុត ១៨០ អង្សា ៤៥ នាទី។"]'::jsonb),
('Fish and Chips', 'ត្រីចៀន និងដំឡូងបំពង', 'British battered fried fish with thick chips and mushy peas.', 'ត្រីស្រោបម្សៅចៀនបែបអង់គ្លេស ជាមួយដំឡូងបំពងក្រាស់ និងសណ្តែកបារាំងកិន។', 840, 'GB', 'main', 40, 2, 'medium', false, 32, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Fish_and_chips_-_Twickenham%2C_UK.jpg/500px-Fish_and_chips_-_Twickenham%2C_UK.jpg', 'Photo: Daderot, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Fish_and_chips_-_Twickenham,_UK.jpg', '["2 white fish fillets", "150 g flour", "200 ml cold sparkling water", "3 large potatoes", "Oil for frying", "Lemon and mushy peas"]'::jsonb, '["សាច់ត្រីស ២ ដុំ", "ម្សៅ ១៥០ ក្រាម", "ទឹកសូដាត្រជាក់ ២០០ មីលីលីត្រ", "ដំឡូងបារាំងធំ ៣ មើម", "ប្រេងសម្រាប់ចៀន", "ក្រូចឆ្មា និងសណ្តែកបារាំងកិន"]'::jsonb, '["Cut the potatoes into thick chips and fry at 150 °C until soft.", "Whisk flour and sparkling water into a batter and coat the fish.", "Fry the fish at 180 °C for 6 minutes, then fry the chips again until crisp."]'::jsonb, '["កាត់ដំឡូងជាបន្ទះក្រាស់ ហើយចៀន ១៥០ អង្សា រហូតទន់។", "វាយម្សៅជាមួយទឹកសូដា ហើយស្រោបត្រី។", "ចៀនត្រី ១៨០ អង្សា ៦ នាទី រួចចៀនដំឡូងម្តងទៀតឱ្យស្រួយ។"]'::jsonb),
('Shepherd''s Pie', 'នំដុតសាច់ចៀមដំឡូង', 'Minced lamb in rich gravy, baked under a golden mashed potato crust.', 'សាច់ចៀមចិញ្ច្រាំក្នុងទឹកខាប់ ដុតក្រោមស្រទាប់ដំឡូងកិនពណ៌មាស។', 560, 'GB', 'main', 75, 4, 'medium', false, 31, 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Shepherds_pie_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg/500px-Shepherds_pie_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg', 'Photo: Andy Li, CC0, via Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shepherds_pie_-_The_Kew_Greenhouse_Cafe_2025-05-14.jpg', '["500 g minced lamb", "1 onion and 1 carrot", "1 tbsp tomato paste", "300 ml stock", "800 g potatoes", "50 g butter and a splash of milk"]'::jsonb, '["សាច់ចៀមចិញ្ច្រាំ ៥០០ ក្រាម", "ខ្ទឹមបារាំង ១ និងការ៉ុត ១", "ប៉េងប៉ោះខាប់ ១ ស្លាបព្រាបាយ", "ទឹកស៊ុប ៣០០ មីលីលីត្រ", "ដំឡូងបារាំង ៨០០ ក្រាម", "ប៊ឺ ៥០ ក្រាម និងទឹកដោះគោបន្តិច"]'::jsonb, '["Brown the lamb with onion and carrot, then add tomato paste and stock and simmer for 20 minutes.", "Boil the potatoes and mash with butter and milk.", "Spread the mash over the meat and bake at 200 °C for 25 minutes until golden."]'::jsonb, '["ឆាសាច់ចៀមជាមួយខ្ទឹមបារាំង និងការ៉ុត រួចដាក់ប៉េងប៉ោះខាប់ និងទឹកស៊ុប រំងាស់ ២០ នាទី។", "ស្ងោរដំឡូង ហើយកិនជាមួយប៊ឺ និងទឹកដោះគោ។", "ពង្រាយដំឡូងកិនលើសាច់ ហើយដុត ២០០ អង្សា ២៥ នាទី រហូតពណ៌មាស។"]'::jsonb)
